package com.dormrepair.v2.catalog;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.flywaydb.core.Flyway;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="flowable.v2B",matches="true")
class DemoInitializerTest {
 DriverManagerDataSource ds;JdbcTemplate j;
 @BeforeEach void reset()throws Exception{ds=new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:5432/dorm_repair_v2_test_demo",System.getenv().getOrDefault("V2_DB_USER","sota"),System.getenv().getOrDefault("V2_DB_PASSWORD",""));try(var c=ds.getConnection()){com.dormrepair.v2.platform.migration.V2DatabaseTarget.requireTestReset(c);}j=new JdbcTemplate(ds);j.execute("drop schema if exists v2_business_history cascade");j.execute("drop schema public cascade");j.execute("create schema public");Flyway.configure().dataSource(ds).locations("classpath:db/v2/business").defaultSchema("v2_business_history").schemas("v2_business_history").group(true).load().migrate();}
 @Test void initialRepeatAndManualEditsArePreserved(){var first=DemoInitializer.initializeForTest(ds);assertTrue(first.get("created")>0);assertEquals(60,j.queryForObject("select count(*) from public.facility",Integer.class));assertEquals(48,j.queryForObject("select count(*) from public.room",Integer.class));String hash=j.queryForObject("select md5(string_agg(qr_token,',' order by id)) from public.facility",String.class);j.update("update public.facility set name='Manually edited' where asset_no='SYNTHETIC_ASSET_1'");assertEquals(0,DemoInitializer.initializeForTest(ds).get("created"));assertEquals(hash,j.queryForObject("select md5(string_agg(qr_token,',' order by id)) from public.facility",String.class));assertEquals("Manually edited",j.queryForObject("select name from public.facility where asset_no='SYNTHETIC_ASSET_1'",String.class));assertEquals(0,j.queryForObject("select count(*) from public.sys_user",Integer.class));}
 @Test void partialCatalogIsCompletedWithoutOverwrite(){j.update("insert into public.campus(code,name) values ('SYNTHETIC_CAMPUS_1','Manual preserved')");DemoInitializer.initializeForTest(ds);assertEquals(2,j.queryForObject("select count(*) from public.campus",Integer.class));assertEquals("Manual preserved",j.queryForObject("select name from public.campus where code='SYNTHETIC_CAMPUS_1'",String.class));}
 @Test void conflictingRelationshipRollsBackEverything(){j.update("insert into public.campus(code,name) values ('OTHER','Other')");j.update("insert into public.building(code,name,campus_id) select 'SYNTHETIC_BUILDING_1_1','Conflict',id from public.campus");assertThrows(IllegalStateException.class,()->DemoInitializer.initializeForTest(ds));assertEquals(1,j.queryForObject("select count(*) from public.campus",Integer.class));assertEquals(0,j.queryForObject("select count(*) from public.facility",Integer.class));}
 @Test void auditFailureRollsBackAllDemoRows(){j.execute("create function public.fail_demo_audit() returns trigger language plpgsql as $$ begin raise exception 'Injected'; end $$");j.execute("create trigger fail_demo before insert on public.audit_event for each row execute function public.fail_demo_audit()");assertThrows(org.springframework.dao.DataAccessException.class,()->DemoInitializer.initializeForTest(ds));assertEquals(0,j.queryForObject("select count(*) from public.campus",Integer.class));assertEquals(0,j.queryForObject("select count(*) from public.facility",Integer.class));}
 @Test void normalEntrypointRejectsTestDatabase(){assertThrows(IllegalStateException.class,()->DemoInitializer.initialize(ds));assertEquals(0,j.queryForObject("select count(*) from public.campus",Integer.class));}
 @Test void manuallyClearedTypeAssociationIsNotRecreated(){DemoInitializer.initializeForTest(ds);long type=j.queryForObject("select id from public.facility_type where code='SYNTHETIC_TYPE_0'",Long.class);j.update("delete from public.facility_type_repair_item where type_id=?",type);DemoInitializer.initializeForTest(ds);assertEquals(0,j.queryForObject("select count(*) from public.facility_type_repair_item where type_id=?",Integer.class,type));}
}
